import { existsSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { CYCLE, CYCLES } from './cycles.js';
import { parseDate } from './dates.js';

/**
 * Where the subscriptions are kept: `--file`, else $SUBTRACK_FILE, else ./subscriptions.json.
 * @param {string | undefined} file
 * @param {Record<string, string | undefined>} [env=process.env]
 * @returns {string}
 */
export function storePath(file, env = process.env) {
  return file || env.SUBTRACK_FILE || 'subscriptions.json';
}

/**
 * Why a subscription is not valid, or null if it is.
 * @param {{ name: string, price: number, cycle: string, since: string }} sub
 * @returns {string | null}
 */
export function validate(sub) {
  if (!sub || typeof sub.name !== 'string' || !sub.name.trim()) return 'a subscription needs a name';
  if (!Number.isInteger(sub.price) || sub.price < 0) return `${sub.name}: price must be whole cents, zero or more (got ${sub.price})`;
  if (!CYCLES.includes(sub.cycle)) return `${sub.name}: unknown billing cycle "${sub.cycle}"`;
  if (parseDate(sub.since) === null) return `${sub.name}: "since" must be a date (YYYY-MM-DD)`;
  return null;
}

// Files written by subtrack 0.1 stored "month" and "year"; read them with today's cycle names.
const V1_NAMES = { month: CYCLE.MONTH, year: CYCLE.YEAR };

function upgrade(sub) {
  return { ...sub, cycle: V1_NAMES[sub.cycle] ?? sub.cycle };
}

/**
 * Throw if a subscription is not valid (the message says why).
 * @param {{ name: string, price: number, cycle: string, since: string }} sub
 */
export function assertValid(sub) {
  const problem = validate(sub);
  if (problem) throw new Error(problem);
}

/**
 * Add a subscription to the list: names are unique (ignoring case) and the plan must be valid.
 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
 * @param {{ name: string, price: number, cycle: string, since: string }} sub
 * @returns {{ name: string, price: number, cycle: string, since: string }}
 */
export function addSubscription(subs, sub) {
  if (subs.some((s) => s.name.toLowerCase() === sub.name.toLowerCase())) throw new Error(`${sub.name} is already on the list`);
  assertValid(sub);
  subs.push(sub);
  return sub;
}

/**
 * Read every subscription from the file (none if it does not exist yet). Throws on an invalid entry.
 * @param {string} path
 * @returns {Array<{ name: string, price: number, cycle: string, since: string }>}
 */
export function load(path) {
  if (!existsSync(path)) return [];
  let data;
  try {
    data = JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    throw new Error(`${path} is not a subtrack file (not valid JSON)`);
  }
  const subs = (data.subscriptions ?? []).map(upgrade);
  for (const sub of subs) {
    const problem = validate(sub);
    if (problem) throw new Error(`${path}: ${problem}`);
  }
  return subs;
}

/**
 * Write every subscription to the file (through a temporary file, so a crash never leaves half a file).
 * @param {string} path
 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
 */
export function save(path, subs) {
  const tmp = `${path}.tmp`;
  writeFileSync(tmp, JSON.stringify({ subscriptions: subs }, null, 2) + '\n');
  renameSync(tmp, path);
}

