#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { CYCLE, monthlyCents, nextCharge } from '../src/cycles.js';
import { parseDate, todayIso } from '../src/dates.js';
import { toCsv } from '../src/export.js';
import { readCsvFile } from '../src/import.js';
import { formatEuros, parseEuros } from '../src/money.js';
import { upcoming } from '../src/renewals.js';
import { addSubscription, assertValid, load, save, storePath } from '../src/store.js';

const USAGE = `usage: subtrack <command> [options]

  add <name> <price> [--every week|month|year] [--since YYYY-MM-DD]
  price <name> <new price>
  list [--every week|month|year]
  total [--yearly]
  renewals [--within <days>]
  export
  import <file.csv>
  remove <name>

options for every command: --file <path>, --today YYYY-MM-DD
set SUBTRACK_DEBUG=1 to see where an error comes from`;

function die(message, code = 1) {
  process.stderr.write(`subtrack: ${message}\n`);
  process.exit(code);
}

// an unexpected error: one line for people, the whole stack with SUBTRACK_DEBUG=1
function fail(err) {
  if (process.env.SUBTRACK_DEBUG) {
    process.stderr.write(`${err.stack}\n`);
    process.exit(1);
  }
  die(err.message);
}

// --every month|year (monthly/yearly work too)
const EVERY = { week: CYCLE.WEEK, weekly: CYCLE.WEEK, month: CYCLE.MONTH, monthly: CYCLE.MONTH, year: CYCLE.YEAR, yearly: CYCLE.YEAR };

function cycleFlag(value = 'month') {
  const cycle = EVERY[value.toLowerCase()];
  if (!cycle) die(`--every must be week, month or year, got "${value}"`, 2);
  return cycle;
}

let parsed;
try {
  parsed = parseArgs({
    args: process.argv.slice(2),
    allowPositionals: true,
    options: {
      every: { type: 'string' },
      since: { type: 'string' },
      within: { type: 'string' },
      today: { type: 'string' },
      yearly: { type: 'boolean' },
      file: { type: 'string' },
      help: { type: 'boolean', short: 'h' },
    },
  });
} catch (err) {
  die(`${err.message}\n\n${USAGE}`, 2);
}
const { values: opts, positionals } = parsed;
const [command, ...args] = positionals;
if (opts.help || !command) {
  console.log(USAGE);
  process.exit(command || opts.help ? 0 : 2);
}

const file = storePath(opts.file);
const today = opts.today === undefined ? todayIso() : parseDate(opts.today);
if (today === null) die(`--today must be a date (YYYY-MM-DD), got "${opts.today}"`, 2);

let subs;
try {
  subs = load(file);
} catch (err) {
  fail(err);
}

switch (command) {
  case 'add': {
    const [name, priceText] = args;
    if (!name || priceText === undefined) die(`add needs a name and a price\n\n${USAGE}`, 2);
    const price = parseEuros(priceText);
    if (price === null) die(`"${priceText}" is not a price (try 12.99)`, 2);
    const since = opts.since === undefined ? today : parseDate(opts.since);
    if (since === null) die(`--since must be a date (YYYY-MM-DD), got "${opts.since}"`, 2);
    const sub = { name, price, cycle: cycleFlag(opts.every), since };
    try {
      addSubscription(subs, sub);
    } catch (err) {
      fail(err);
    }
    save(file, subs);
    console.log(`Added ${name}: ${formatEuros(price)} ${sub.cycle}, ${formatEuros(monthlyCents(sub))} a month, next charge ${nextCharge(sub, today)}.`);
    break;
  }
  case 'price': {
    const [name, priceText] = args;
    if (!name || priceText === undefined) die(`price needs a name and a new price\n\n${USAGE}`, 2);
    const price = parseEuros(priceText);
    if (price === null) die(`"${priceText}" is not a price (try 12.99)`, 2);
    const sub = subs.find((s) => s.name.toLowerCase() === name.toLowerCase());
    if (!sub) die(`${name} is not on the list`);
    const changed = { ...sub, price };
    try {
      assertValid(changed);
    } catch (err) {
      fail(err);
    }
    Object.assign(sub, changed);
    save(file, subs);
    console.log(`${sub.name} now costs ${formatEuros(price)} ${sub.cycle}, ${formatEuros(monthlyCents(sub))} a month.`);
    break;
  }
  case 'list': {
    if (!subs.length) {
      console.log('No subscriptions yet. Add one with: subtrack add <name> <price>');
      break;
    }
    const width = Math.max(...subs.map((s) => s.name.length));
    const only = opts.every === undefined ? null : cycleFlag(opts.every);
    const sorted = subs.filter((s) => !only || s.cycle === only).sort((a, b) => a.name.localeCompare(b.name));
    for (const s of sorted) {
      console.log(`${s.name.padEnd(width)}  ${formatEuros(s.price).padStart(10)} ${s.cycle.padEnd(8)} ${formatEuros(monthlyCents(s)).padStart(10)} a month`);
    }
    break;
  }
  case 'total': {
    const total = subs.reduce((sum, s) => sum + monthlyCents(s), 0);
    const plans = `${subs.length} ${subs.length === 1 ? 'plan' : 'plans'}`;
    if (opts.yearly) console.log(`Yearly total: ${formatEuros(total * 12)} (${plans})`);
    else console.log(`Monthly total: ${formatEuros(total)} (${plans})`);
    break;
  }
  case 'renewals': {
    const within = opts.within === undefined ? 30 : Number(opts.within);
    if (!Number.isInteger(within) || within < 0) die(`--within must be a whole number of days, got "${opts.within}"`, 2);
    const rows = upcoming(subs, today, within);
    if (!rows.length) {
      console.log(`Nothing renews in the next ${within} days.`);
      break;
    }
    const width = Math.max(...rows.map((r) => r.name.length));
    for (const r of rows) {
      console.log(`${r.when.padEnd(6)}  ${r.name.padEnd(width)}  ${formatEuros(r.price)}`);
    }
    break;
  }
  case 'export':
    process.stdout.write(toCsv(subs, today));
    break;
  case 'import': {
    const [csvPath] = args;
    if (!csvPath) die(`import needs a CSV file\n\n${USAGE}`, 2);
    let rows = [];
    try {
      rows = readCsvFile(csvPath);
      for (const sub of rows) addSubscription(subs, sub);
    } catch (err) {
      fail(err);
    }
    save(file, subs);
    console.log(`Imported ${rows.length} ${rows.length === 1 ? 'plan' : 'plans'} from ${csvPath}.`);
    break;
  }
  case 'remove': {
    const [name] = args;
    if (!name) die(`remove needs a name\n\n${USAGE}`, 2);
    const left = subs.filter((s) => s.name.toLowerCase() !== String(name).toLowerCase());
    if (left.length === subs.length) die(`${name} is not on the list`);
    save(file, left);
    console.log(`Removed ${name}.`);
    break;
  }
  default:
    die(`unknown command "${command}"\n\n${USAGE}`, 2);
}

