1	import { decimalCommaToCents, isDecimalComma } from './locale.js';
2	
3	const DECIMAL_POINT = /^(\d{1,3}(,\d{3})+|\d+)(\.\d{1,2})?$/; // 12.99, 1,299.00
4	
5	/**
6	 * Parse a euro amount typed by a person ("12", "12.5", "1,299.00", "12,99", "1.299,00", "€12.99") into whole cents.
7	 * Returns null when the text is not an amount.
8	 * @param {string} text
9	 * @returns {number | null}
10	 */
11	export function parseEuros(text) {
12	  const s = String(text).trim().replace(/^€\s*|\s*€$/g, '');
13	  if (DECIMAL_POINT.test(s)) return Number(Number(s.replace(/,/g, '')).toFixed(2)) * 100;
14	  if (isDecimalComma(s)) return decimalCommaToCents(s); // '12,99' style: converted in locale.js
15	  return null;
16	}
17	
18	/**
19	 * A price cell from a spreadsheet ("12.99", "12,99" or "€12.99") in whole cents, or null. Used by import.
20	 * @param {string} text
21	 * @returns {number | null}
22	 */
23	export function cellCents(text) {
24	  const s = String(text).trim().replace(/^€\s*|\s*€$/g, '').replace(/^(\d+),(\d{1,2})$/, '$1.$2');
25	  return /^\d+(\.\d{1,2})?$/.test(s) ? Number(s) * 100 : null;
26	}
27	
28	/**
29	 * Format whole cents as euros: 123456 -> "€1,234.56".
30	 * @param {number} cents
31	 * @returns {string}
32	 */
