import { decimalCommaToCents, isDecimalComma } from './locale.js';

const DECIMAL_POINT = /^(\d{1,3}(,\d{3})+|\d+)(\.\d{1,2})?$/; // 12.99, 1,299.00

/**
 * Parse a euro amount typed by a person ("12", "12.5", "1,299.00", "12,99", "1.299,00", "€12.99") into whole cents.
 * Returns null when the text is not an amount.
 * @param {string} text
 * @returns {number | null}
 */
export function parseEuros(text) {
  const s = String(text).trim().replace(/^€\s*|\s*€$/g, '');
  if (DECIMAL_POINT.test(s)) return Number(Number(s.replace(/,/g, '')).toFixed(2)) * 100;
  if (isDecimalComma(s)) return decimalCommaToCents(s); // '12,99' style: converted in locale.js
  return null;
}

/**
 * A price cell from a spreadsheet ("12.99", "12,99" or "€12.99") in whole cents, or null. Used by import.
 * @param {string} text
 * @returns {number | null}
 */
export function cellCents(text) {
  const s = String(text).trim().replace(/^€\s*|\s*€$/g, '').replace(/^(\d+),(\d{1,2})$/, '$1.$2');
  return /^\d+(\.\d{1,2})?$/.test(s) ? Number(s) * 100 : null;
}

/**
 * Format whole cents as euros: 123456 -> "€1,234.56".
 * @param {number} cents
 * @returns {string}
 */
export function formatEuros(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
}

/**
 * Format whole cents as a plain decimal for files: 123456 -> "1234.56".
 * @param {number} cents
 * @returns {string}
 */
export function plainEuros(cents) {
  return (cents / 100).toFixed(2);
}

